const event=(c:any,p:string,t:string,correlation:string,payload:object)=>c.query(`INSERT INTO events(project_id,event_type,correlation_id,payload,actor_id) VALUES($1,$2,$3,$4,$5)`,[p,t,correlation,payload,config().operatorId]);
/** Criterion IDs are versioned data persisted at module-revision creation. String criteria get a stable positional ID; object criteria preserve their explicit ID. */
const versionedCriteria=(acceptanceCriteria:unknown):any[]=>Array.isArray(acceptanceCriteria)?acceptanceCriteria.map((x:any,i:number)=>typeof x==='string'?{criterion_id:`criterion-${i+1}`,text:x}:typeof x==='object'&&x!==null&&typeof x.criterion_id==='string'?x:{criterion_id:`criterion-${i+1}`,text:String(x?.text??'')}):[];
const key=(v:unknown)=>typeof v==='string'&&/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(v);
const idem=async(c:any,k:string)=>{const r=await c.query(`SELECT id FROM operations WHERE idempotency_key=$1`,[k]);return r.rows[0]?.id as string|undefined};
const operation=async(c:any,p:string,kind:string,k:string,correlation:string)=>{const id=randomUUID();await c.query(`INSERT INTO operations(id,project_id,kind,status,idempotency_key,correlation_id) VALUES($1,$2,$3,'SUCCEEDED',$4,$5)`,[id,p,kind,k,correlation]);return id};
const moduleTarget=async(c:any,state:string,trigger:string)=>{const q=await c.query(`SELECT wt.to_state FROM workflow_transitions wt JOIN workflow_definitions wd ON wd.id=wt.workflow_id WHERE wd.code='MODULE_DELIVERY' AND wd.version=1 AND wd.status='PUBLISHED' AND wt.from_state=$1 AND wt.trigger_code=$2`,[state,trigger]);if(!q.rowCount)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');return q.rows[0].to_state as string};
const evidence=async(c:any,p:string,type:string,data:object,op:string)=>{const json=JSON.stringify({schema_version:1,...data});const a=await putArtifact(c,p,type,json,op);const md=await putArtifact(c,p,`${type}-markdown`,`# ${type}\n\n\`\`\`json\n${json}\n\`\`\`\n`,op);return{json:a,markdown:md};};
const baselineReference=(value:any)=>typeof value==='string'?value:null;
const paths=(value:unknown)=>Array.isArray(value)&&value.length>0&&value.every(path=>typeof path==='string'&&path.length<=512&&!path.startsWith('/')&&!path.includes('\\')&&!path.split('/').includes('..'));
const textList=(value:unknown)=>Array.isArray(value)&&value.length>0&&value.every(item=>typeof item==='string'&&item.trim().length>0);
const workItemContract=(item:any)=>{
  if(!item||typeof item!=='object'||typeof item.title!=='string'||!item.title.trim()||!textList(item.inputs)||!paths(item.allowlist)||!Array.isArray(item.denylist)||!item.denylist.every((path:unknown)=>typeof path==='string'&&path.length>0&&!path.startsWith('/')&&!path.includes('\\')&&!path.split('/').includes('..'))||typeof item.output!=='string'||!item.output.trim()||!textList(item.acceptance_criteria)||!Array.isArray(item.dependencies)||!Array.isArray(item.qa_matrix)||!item.qa_matrix.length||!item.qa_matrix.every((entry:any)=>entry&&typeof entry==='object'&&typeof entry.command==='string'&&entry.command.trim()&&typeof entry.cwd==='string'&&entry.cwd.trim()&&Number.isInteger(entry.timeout_seconds)&&entry.timeout_seconds>0&&textList(entry.acceptance_criteria))) throw new ApiError(422,'WORK_ITEM_CONTRACT_INVALID');
  const allow=new Set(item.allowlist), deny=new Set(item.denylist); if(allow.size!==item.allowlist.length||deny.size!==item.denylist.length||[...allow].some(path=>deny.has(path))) throw new ApiError(422,'WORK_ITEM_PATH_POLICY_INVALID');
};

export const materializeModule=async(projectId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const moduleKey=body.module_key;if(!key(moduleKey))throw new ApiError(422,'MODULE_KEY_INVALID');const p=(await c.query(`SELECT state,workflow_code,workflow_version,archived_at FROM projects WHERE id=$1 FOR UPDATE`,[projectId])).rows[0];if(!p)throw new ApiError(404,'PROJECT_NOT_FOUND');let baselineRevisionId:string|null=null;if(p.workflow_code==='PROJECT_DISCOVERY'&&p.workflow_version===3){if(p.archived_at)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const requested=typeof body.technology_baseline_revision_id==='string'?body.technology_baseline_revision_id:null;const baseline=(await c.query(`SELECT id FROM technology_baseline_revisions WHERE project_id=$1 AND status='APPROVED' AND ($2::uuid IS NULL OR id=$2) ORDER BY revision_number DESC LIMIT 1 FOR SHARE`,[projectId,requested])).rows[0];if(!baseline)throw new ApiError(409,requested?'TECHNOLOGY_BASELINE_REVISION_NOT_APPROVED':'TECHNOLOGY_BASELINE_APPROVAL_REQUIRED');baselineRevisionId=baseline.id;}else if(p.state!=='PRODUCT_COMMITMENT')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const rev=randomUUID(),moduleId=randomUUID(),round=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'MATERIALIZE_MODULE',idempotencyKey,correlation);const payload={schema_version:1,module_key:moduleKey,name:body.name,objective:body.objective,scope:body.scope,out_of_scope:body.out_of_scope,dependencies:body.dependencies,acceptance_criteria:body.acceptance_criteria,source_gate:body.source_gate};const criteria=versionedCriteria(body.acceptance_criteria);await c.query(`INSERT INTO module_revisions(id,project_id,module_key,revision,payload,status,technology_baseline_revision_id,criteria) VALUES($1,$2,$3,1,$4,'PENDING_APPROVAL',$5,$6::jsonb)`,[rev,projectId,moduleKey,payload,baselineRevisionId,JSON.stringify(criteria)]);await c.query(`INSERT INTO modules(id,project_id,module_key,current_revision_id,technology_baseline_revision_id) VALUES($1,$2,$3,$4,$5)`,[moduleId,projectId,moduleKey,rev,baselineRevisionId]);await c.query(`INSERT INTO module_rounds(id,module_id,revision_id,round_number,state) VALUES($1,$2,$3,1,'WAITING_FOR_MODULE_APPROVAL')`,[round,moduleId,rev]);const artifacts=await evidence(c,projectId,'module-definition',{...payload,module_id:moduleId,revision_id:rev,technology_baseline_revision_id:baselineRevisionId,round_id:round,correlation_id:correlation},op);const gateId=randomUUID();await c.query(`INSERT INTO module_gates(id,project_id,module_id,revision_id,round_id,kind,evidence,technology_baseline_revision_id) VALUES($1,$2,$3,$4,$5,'MODULE_APPROVAL',$6,$7)`,[gateId,projectId,moduleId,rev,round,{definition_hash:artifacts.json.hash},baselineRevisionId]);await event(c,projectId,'MODULE_MATERIALIZED',correlation,{module_id:moduleId,module_key:moduleKey,revision_id:rev,technology_baseline_revision_id:baselineRevisionId,gate_id:gateId,evidence_hash:artifacts.json.hash});return{operation_id:op,status:'ACCEPTED',module_id:moduleId,revision_id:rev,gate_id:gateId};});

export const decideModule=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const m=await c.query(`SELECT m.*,r.id revision_id FROM modules m JOIN module_revisions r ON r.id=m.current_revision_id WHERE m.id=$1 AND m.project_id=$2 FOR UPDATE`,[moduleId,projectId]);if(!m.rowCount)throw new ApiError(404,'MODULE_NOT_FOUND');const gate=(await c.query(`SELECT * FROM module_gates WHERE module_id=$1 AND revision_id=$2 AND kind='MODULE_APPROVAL' AND status='OPEN' FOR UPDATE`,[moduleId,m.rows[0].revision_id])).rows[0];if(!gate||Number(body.version)!==gate.version)throw new ApiError(409,'GATE_VERSION_CONFLICT');const approved=body.decision==='APPROVED',feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!approved&&!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');if(!approved&&body.decision!=='REJECTED')throw new ApiError(422,'GATE_DECISION_INVALID');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_MODULE',idempotencyKey,correlation);if(approved){const target=await moduleTarget(c,m.rows[0].state,'DECIDE_MODULE_APPROVED');await c.query(`UPDATE module_revisions SET status='APPROVED',approved_gate_id=$2 WHERE id=$1`,[m.rows[0].revision_id,gate.id]);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[gate.round_id,target]);}else await c.query(`UPDATE module_revisions SET status='REJECTED' WHERE id=$1`,[m.rows[0].revision_id]);await c.query(`UPDATE module_gates SET status=$2,decision=$3,feedback=$4,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,approved?'APPROVED':'REJECTED',body.decision,feedback]);await event(c,projectId,approved?'MODULE_APPROVED':'MODULE_REJECTED',correlation,{module_id:moduleId,gate_id:gate.id,feedback});return{operation_id:op,status:'ACCEPTED'};});

export const completeDefinition=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const old=await idem(c,idempotencyKey);if(old)return{operation_id:old,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const target=await moduleTarget(c,m.state,'DEFINITION_COMPLETED'),round=(await c.query(`SELECT * FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1 FOR UPDATE`,[moduleId])).rows[0],correlation=randomUUID(),op=await operation(c,projectId,'COMPLETE_MODULE_DEFINITION',idempotencyKey,correlation);const artifacts=await evidence(c,projectId,'module-definition',{module_id:moduleId,revision_id:m.current_revision_id,round_id:round.id,...body,correlation_id:correlation},op),gateId=randomUUID();await c.query(`INSERT INTO module_gates(id,project_id,module_id,revision_id,round_id,kind,evidence) VALUES($1,$2,$3,$4,$5,'ARCHITECTURE_DECISION',$6)`,[gateId,projectId,moduleId,m.current_revision_id,round.id,{artifact_hash:artifacts.json.hash}]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[round.id,target]);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await event(c,projectId,'MODULE_DEFINITION_COMPLETED',correlation,{module_id:moduleId,gate_id:gateId,evidence_hash:artifacts.json.hash});return{operation_id:op,status:'ACCEPTED',gate_id:gateId};});
export const decideArchitecture=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const gate=(await c.query(`SELECT * FROM module_gates WHERE module_id=$1 AND kind='ARCHITECTURE_DECISION' AND status='OPEN' FOR UPDATE`,[moduleId])).rows[0];if(!gate||Number(body.version)!==gate.version)throw new ApiError(409,'GATE_VERSION_CONFLICT');const approved=body.decision==='APPROVED',feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!approved&&!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_ARCHITECTURE',idempotencyKey,correlation);let planned:any; if(approved){const target=await moduleTarget(c,m.state,'DECIDE_ARCHITECTURE');const artifacts=await evidence(c,projectId,'module-architecture',{module_id:moduleId,revision_id:m.current_revision_id,round_id:gate.round_id,decision:body.decision,alternatives:body.alternatives??[],consequences:body.consequences??[],risks:body.risks??[],correlation_id:correlation},op);await c.query(`UPDATE modules SET state=$2,version=version+1 WHERE id=$1`,[moduleId,target]);await c.query(`UPDATE module_rounds SET state=$2 WHERE id=$1`,[gate.round_id,target]);await c.query(`UPDATE module_gates SET status='APPROVED',decision=$2,feedback=$3,decided_at=clock_timestamp(),evidence=evidence||$4 WHERE id=$1`,[gate.id,body.decision,feedback,{architecture_hash:artifacts.json.hash}]);planned=await enqueuePlan(c,projectId,m,`plan-module:${moduleId}:initial`);}else await c.query(`UPDATE module_gates SET status='REJECTED',decision=$2,feedback=$3,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,body.decision,feedback]);await event(c,projectId,approved?'ARCHITECTURE_APPROVED':'ARCHITECTURE_REJECTED',correlation,{module_id:moduleId,gate_id:gate.id,plan_operation_id:planned?.op,plan_job_id:planned?.job});return{operation_id:op,status:'ACCEPTED',plan_operation_id:planned?.op};});
const legacyApproveModulePlan=async(..._args:any[])=>{throw new ApiError(410,'PHASE3_LEGACY_COMMAND_DISABLED');};
export const approveModulePlan=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED',evidence_hash:null};const m=(await c.query(`SELECT m.*,r.payload revision_payload,r.criteria revision_criteria FROM modules m JOIN module_revisions r ON r.id=m.current_revision_id WHERE m.id=$1 AND m.project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0],p=(await c.query(`SELECT * FROM module_plan_revisions WHERE id=$1 AND module_id=$2 FOR UPDATE`,[body.plan_revision_id,moduleId])).rows[0],g=(await c.query(`SELECT * FROM module_gates WHERE module_id=$1 AND plan_revision_id=$2 AND kind='MODULE_PLAN_APPROVAL' AND status='OPEN' FOR UPDATE`,[moduleId,body.plan_revision_id])).rows[0];if(!m||m.state!=='PLANNING_IN_PROGRESS'||!p||!g||Number(body.version)!==g.version)throw new ApiError(409,'PLAN_REVISION_CONFLICT');try{revalidatePlanApproval(p);}catch(error){const code=error instanceof ApiError?error.code:'MODULE_PLAN_APPROVAL_VALIDATION_FAILED';const failureExecution=randomUUID();await withTransaction(async ec=>{await evidence(ec,projectId,'module-plan-approval-validation-failed',{module_id:moduleId,plan_revision_id:p.id,code},failureExecution);await event(ec,projectId,'MODULE_PLAN_APPROVAL_VALIDATION_FAILED',randomUUID(),{module_id:moduleId,plan_revision_id:p.id,code});});throw error instanceof ApiError?error:new ApiError(422,'MODULE_PLAN_APPROVAL_VALIDATION_FAILED');}const items=p.payload.work_items;const round=(await c.query(`SELECT * FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1 FOR UPDATE`,[moduleId])).rows[0],correlation=randomUUID(),op=await operation(c,projectId,'APPROVE_MODULE_PLAN',idempotencyKey,correlation),ids:string[]=[],blocked=new Set<string>(),blockers=new Map<string,{dependency_id:string;justification:string}>();for(const d of p.payload.business_dependency_coverage??[]){if(d?.classification==='EXTERNAL_BLOCKER')for(const wid of d.blocked_work_item_ids??[]){blocked.add(wid);blockers.set(wid,{dependency_id:d.dependency_id,justification:d.justification});}}for(const item of items){const id=randomUUID();ids.push(id);const payload={schema_version:1,...item,plan_revision_id:p.id,plan_artifact_hash:p.json_artifact_hash};if(blocked.has(item.work_item_id)){payload.external_blocked=true;payload.external_blocked_dependency_id=blockers.get(item.work_item_id)?.dependency_id;payload.external_blocked_justification=blockers.get(item.work_item_id)?.justification;payload.blocked_state='EXTERNAL_BLOCKED';}await c.query(`INSERT INTO work_items(id,project_id,module_id,revision_id,round_id,title,payload,technology_baseline_revision_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,[id,projectId,moduleId,m.current_revision_id,round.id,item.title,payload,m.technology_baseline_revision_id]);}await c.query(`UPDATE module_plan_revisions SET status='APPROVED' WHERE id=$1`,[p.id]);await c.query(`UPDATE module_gates SET status='APPROVED',decision='APPROVED',decided_at=clock_timestamp() WHERE id=$1`,[g.id]);await c.query(`UPDATE module_rounds SET state='WORK_ITEMS_ACTIVE',completed_at=clock_timestamp() WHERE id=$1`,[round.id]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id=$1`,[moduleId]);if(blocked.size){await evidence(c,projectId,'module-plan-external-blocker',{module_id:moduleId,plan_revision_id:p.id,blocked_work_item_ids:[...blocked],blockers:[...blockers.entries()].map(([work_item_id,b])=>({work_item_id,dependency_id:b.dependency_id,justification:b.justification})),correlation_id:correlation},op);await event(c,projectId,'MODULE_PLAN_EXTERNAL_BLOCKED',correlation,{module_id:moduleId,plan_revision_id:p.id,blocked_work_item_ids:[...blocked]});}await event(c,projectId,'MODULE_PLAN_APPROVED',correlation,{module_id:moduleId,plan_revision_id:p.id,work_item_ids:ids,blocked_work_item_ids:[...blocked]});return{operation_id:op,status:'ACCEPTED',work_item_ids:ids,blocked_work_item_ids:[...blocked],evidence_hash:p.json_artifact_hash};});
export const startModuleRevision=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const m=(await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId])).rows[0];if(!m)throw new ApiError(404,'MODULE_NOT_FOUND');const previous=m.current_revision_id,old=(await c.query(`SELECT * FROM module_revisions WHERE id=$1 FOR UPDATE`,[previous])).rows[0],rejectedGate=Boolean((await c.query(`SELECT 1 FROM module_gates WHERE module_id=$1 AND revision_id=$2 AND kind='MODULE_APPROVAL' AND status='REJECTED' FOR SHARE`,[moduleId,previous])).rowCount);if((old.status!=='REJECTED'&&!rejectedGate)||m.state!=='WAITING_FOR_MODULE_APPROVAL')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const payload={...old.payload,...body,module_key:m.module_key,schema_version:1,supersedes_revision_id:previous},baselineRevisionId=baselineReference(old.technology_baseline_revision_id),revision=randomUUID(),round=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'RESUBMIT_MODULE_REVISION',idempotencyKey,correlation);await c.query(`UPDATE module_revisions SET status='SUPERSEDED' WHERE id=$1`,[previous]);await c.query(`INSERT INTO module_revisions(id,project_id,module_key,revision,payload,status,technology_baseline_revision_id,criteria) VALUES($1,$2,$3,$4,$5,'PENDING_APPROVAL',$6,$7::jsonb)`,[revision,projectId,m.module_key,Number(old.revision)+1,payload,baselineRevisionId,JSON.stringify(versionedCriteria(payload.acceptance_criteria))]);await c.query(`INSERT INTO module_rounds(id,module_id,revision_id,round_number,state) SELECT $1,$2,$3,coalesce(max(round_number),0)+1,'WAITING_FOR_MODULE_APPROVAL' FROM module_rounds WHERE module_id=$2`,[round,moduleId,revision]);await c.query(`UPDATE modules SET current_revision_id=$2,state='WAITING_FOR_MODULE_APPROVAL',version=version+1 WHERE id=$1`,[moduleId,revision]);const artifacts=await evidence(c,projectId,'module-definition',{...payload,module_id:moduleId,revision_id:revision,technology_baseline_revision_id:baselineRevisionId,round_id:round,correlation_id:correlation},op),gateId=randomUUID();await c.query(`INSERT INTO module_gates(id,project_id,module_id,revision_id,round_id,kind,evidence,technology_baseline_revision_id) VALUES($1,$2,$3,$4,$5,'MODULE_APPROVAL',$6,$7)`,[gateId,projectId,moduleId,revision,round,{definition_hash:artifacts.json.hash},baselineRevisionId]);await event(c,projectId,'MODULE_REVISION_STARTED',correlation,{module_id:moduleId,revision_id:revision,supersedes_revision_id:previous,technology_baseline_revision_id:baselineRevisionId});await event(c,projectId,'MODULE_RESUBMITTED',correlation,{module_id:moduleId,revision_id:revision,gate_id:gateId,technology_baseline_revision_id:baselineRevisionId});return{operation_id:op,status:'ACCEPTED',revision_id:revision,gate_id:gateId};});

export const authorizeWorkItem=async(projectId:string,moduleId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const existing=await idem(c,idempotencyKey);if(existing)return{operation_id:existing,status:'ACCEPTED'};const m=await c.query(`SELECT * FROM modules WHERE id=$1 AND project_id=$2 FOR UPDATE`,[moduleId,projectId]);if(!m.rowCount)throw new ApiError(404,'MODULE_NOT_FOUND');workItemContract(body);const round=(await c.query(`SELECT id FROM module_rounds WHERE module_id=$1 ORDER BY round_number DESC LIMIT 1`,[moduleId])).rows[0],baselineRevisionId=baselineReference(m.rows[0].technology_baseline_revision_id);const id=randomUUID(),correlation=randomUUID(),op=await operation(c,projectId,'AUTHORIZE_WORK_ITEM',idempotencyKey,correlation);const payload={schema_version:1,inputs:body.inputs,allowlist:body.allowlist,denylist:body.denylist,output:body.output,acceptance_criteria:body.acceptance_criteria,dependencies:body.dependencies,qa_matrix:body.qa_matrix,authorized_by:config().operatorId,authorized_at:new Date().toISOString()};const artifact=await evidence(c,projectId,'module-plan',{work_item_id:id,technology_baseline_revision_id:baselineRevisionId,...payload,correlation_id:correlation},op);await c.query(`INSERT INTO work_items(id,project_id,module_id,revision_id,round_id,title,payload,technology_baseline_revision_id) VALUES($1,$2,$3,$4,$5,$6,$7,$8)`,[id,projectId,moduleId,m.rows[0].current_revision_id,round.id,(body.title as string).trim(),{...payload,plan_artifact_hash:artifact.json.hash},baselineRevisionId]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id=$1`,[moduleId]);await event(c,projectId,'WORK_ITEM_AUTHORIZED',correlation,{work_item_id:id,module_id:moduleId,technology_baseline_revision_id:baselineRevisionId,evidence_hash:artifact.json.hash});return{operation_id:op,status:'ACCEPTED',work_item_id:id,evidence_hash:artifact.json.hash};});

export const phase3Detail=async(projectId:string)=>{
  const [modules,workItems,deliveries,findings,candidates,gates,planningJobs,artifacts,plans,planningOperations,planningTelemetry]=await Promise.all([
    pool.query(`SELECT m.id,m.module_key,m.state,m.version,m.created_at,extract(epoch FROM clock_timestamp()-m.created_at)::integer AS duration_seconds,r.id AS revision_id,r.revision,r.status AS revision_status,r.technology_baseline_revision_id,r.payload->>'name' AS name,r.payload->>'objective' AS objective,r.payload->'scope' AS scope,r.payload->'out_of_scope' AS out_of_scope,r.payload->'dependencies' AS dependencies,r.payload->'acceptance_criteria' AS acceptance_criteria FROM modules m JOIN module_revisions r ON r.id=m.current_revision_id WHERE m.project_id=$1 ORDER BY m.created_at`,[projectId]),
    pool.query(`SELECT id,module_id,title,state,version,rework_rounds,payload->'depends_on_ids' AS depends_on_ids,payload->>'work_item_id' AS plan_work_item_id,coalesce((payload->>'external_blocked')::boolean,false) AS external_blocked,payload->>'external_blocked_justification' AS external_blocked_justification,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds FROM work_items WHERE project_id=$1 ORDER BY created_at`,[projectId]),
    pool.query(`SELECT id,work_item_id,base_sha,head_sha,phase_before_sha,phase_head_sha,state,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds,validations FROM deliveries WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,delivery_id,candidate_id,origin,severity,state,rule_code,description,created_at FROM findings WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,phase_sha,state,blocked_kind,version,created_at,extract(epoch FROM clock_timestamp()-created_at)::integer AS duration_seconds FROM integration_candidates WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,module_id,revision_id,plan_revision_id,kind,version,status,decision,feedback,opened_at,decided_at,evidence FROM module_gates WHERE project_id=$1 ORDER BY opened_at DESC`,[projectId]),
    pool.query(`SELECT id,operation_id,module_id,kind,status,attempts,available_at AS created_at,completed_at,last_error,started_at,last_operational_event_at,last_signal_at,operational_event_count,discarded_event_count,interrupted_reason FROM jobs WHERE project_id=$1 AND kind IN ('PLAN_MODULE_WORK_ITEMS','RETRY_MODULE_PLAN','REQUEST_PLAN_ADJUSTMENT') ORDER BY available_at DESC`,[projectId]),
    pool.query(`SELECT artifact_type,sha256,created_at FROM artifacts WHERE project_id=$1 ORDER BY created_at DESC`,[projectId]),
    pool.query(`SELECT id,module_id,revision_number,status,payload,feedback,json_artifact_hash,markdown_artifact_hash,author_id,supersedes_revision_id,technology_baseline_revision_id,created_at FROM module_plan_revisions WHERE project_id=$1 ORDER BY revision_number DESC,created_at DESC`,[projectId]),
    pool.query(`SELECT o.id,o.kind,o.status,o.failure_code,o.retry_of_operation_id,o.origin_operation_id,o.created_at,o.completed_at,j.module_id FROM operations o JOIN jobs j ON j.operation_id=o.id WHERE o.project_id=$1 AND o.kind IN ('PLAN_MODULE_WORK_ITEMS','RETRY_MODULE_PLAN','REQUEST_PLAN_ADJUSTMENT') ORDER BY o.created_at DESC`,[projectId]),
    pool.query(`SELECT operation_id,module_id,started_at,last_operational_event_at,last_signal_at,heartbeat_count,operational_event_count,discarded_event_count,terminated_at,interrupted_reason,duration_ms FROM module_plan_telemetry WHERE project_id=$1 ORDER BY started_at DESC`,[projectId])
  ]);
  const expose=(rows:any[])=>rows.map(row=>publicValue({...row,...(typeof row.state==='string'?{next_action:nextAction(row.state,row.blocked_kind)}:{})}));
  // F5-23 pendency 13: project an explicit, auditable planning state per module. On the
  // first round with no valid proposal, expose "planning failed, no proposal available"
  // including the failed planning job/operation and a RETRY_MODULE_PLAN action — without
  // ever flipping the module or project into a global failure state.
  // F5-23 pendency 21: expose executor status, allowed stage, time of last signal,
  // duration and health condition, updated live via SSE. The status is one of
  // "na fila", "em execução", "ativo sem evento novo" or "degradado". A heartbeat
  // only proves liveness (last_signal_at); only last_operational_event_at /
  // operational_event_count reflect functional progress.
  const planning=modules.rows.map((m:any)=>{
    // F5-23 pendency 23: the projection ALWAYS points to an eligible origin. A retry action
    // can only reference a terminal PLAN_MODULE_WORK_ITEMS or RETRY_MODULE_PLAN operation of
    // this module (never a REQUEST_PLAN_ADJUSTMENT failure), so the latest such operation is
    // selected and exposed with its lineage (retry_of_operation_id / origin_operation_id).
    const failedOps=(planningOperations.rows as any[]).filter((o:any)=>o.module_id===m.id&&o.status==='FAILED'&&(o.kind==='PLAN_MODULE_WORK_ITEMS'||o.kind==='RETRY_MODULE_PLAN'));
    const terminalFailed=failedOps[0]??null;
    const active=(planningJobs.rows as any[]).find((j:any)=>j.module_id===m.id&&['PENDING','RETRYABLE','LEASED'].includes(j.status));
    const hasProposal=(plans.rows as any[]).some((p:any)=>p.module_id===m.id&&p.status==='PLAN_PROPOSED');
    const telemetry=(planningTelemetry.rows as any[]).find((t:any)=>t.module_id===m.id)??(active?(planningTelemetry.rows as any[]).find((t:any)=>t.operation_id===active.operation_id):null);
    let state:'PLANNING'|'PLANNING_FAILED'|'PLANNING_PROPOSED'='PLANNING';
    if(hasProposal)state='PLANNING_PROPOSED';
    else if(terminalFailed&&!active)state='PLANNING_FAILED';
    const terminated=Boolean(telemetry?.terminated_at)||(!active&&state!=='PLANNING_PROPOSED'&&Boolean(terminalFailed));
    const cfg=config();
    const {executorStatus: executor_status,health}=derivePlanStatus({
      jobStatus:active?.status??null,
      lastSignalAt:active?.last_signal_at??telemetry?.last_signal_at??null,
      startedAt:active?.started_at??telemetry?.started_at??null,
      terminated,
      noSignalSeconds:cfg.planNoSignalSeconds,
      timeoutSeconds:cfg.planTimeoutSeconds
    });
    const lastSignal=active?.last_signal_at??telemetry?.last_signal_at??null;
    const lastOperational=active?.last_operational_event_at??telemetry?.last_operational_event_at??null;
    const durationMs=telemetry?.duration_ms??(telemetry?.started_at&&!terminated?Math.max(0,Date.now()-Date.parse(telemetry.started_at)):null);
    return {module_id:m.id,module_key:m.module_key,module_state:m.state,state,planning_failed:state==='PLANNING_FAILED',
      message:state==='PLANNING_FAILED'?'planejamento falhou, sem proposta disponível':undefined,
      retry_action:state==='PLANNING_FAILED'?{type:'RETRY_MODULE_PLAN',failed_operation_id:terminalFailed?.id??null}:null,
      failed_operation:terminalFailed?{id:terminalFailed.id,kind:terminalFailed.kind,status:terminalFailed.status,failure_code:terminalFailed.failure_code,retry_of_operation_id:terminalFailed.retry_of_operation_id,origin_operation_id:terminalFailed.origin_operation_id,completed_at:terminalFailed.completed_at}:null,
      active_job:active?{id:active.id,kind:active.kind,status:active.status,operation_id:active.operation_id,started_at:active.started_at??null,last_signal_at:active.last_signal_at??null,last_operational_event_at:active.last_operational_event_at??null,operational_event_count:active.operational_event_count??0,discarded_event_count:active.discarded_event_count??0}:null,
      executor_status,
      health,
      allowed_stage:state==='PLANNING_PROPOSED'?'REVIEW_PLAN':active?.status==='LEASED'?'PLAN_EXECUTION':'QUEUED',
      last_signal_at:lastSignal,
      last_operational_event_at:lastOperational,
      duration_ms:durationMs,
      telemetry:telemetry?publicValue({started_at:telemetry.started_at,last_operational_event_at:telemetry.last_operational_event_at,last_signal_at:telemetry.last_signal_at,heartbeat_count:telemetry.heartbeat_count,operational_event_count:telemetry.operational_event_count,discarded_event_count:telemetry.discarded_event_count,terminated_at:telemetry.terminated_at,interrupted_reason:telemetry.interrupted_reason,duration_ms:telemetry.duration_ms}):null,
      proposal:(plans.rows as any[]).find((p:any)=>p.module_id===m.id&&p.status==='PLAN_PROPOSED')?{plan_revision_id:(plans.rows as any[]).find((p:any)=>p.module_id===m.id&&p.status==='PLAN_PROPOSED')?.id}:null};
  });
  const workItemByReference=new Map<string,any>();for(const item of workItems.rows){workItemByReference.set(item.id,item);if(typeof item.plan_work_item_id==='string')workItemByReference.set(item.plan_work_item_id,item);}const projectedWorkItems=workItems.rows.map((item:any)=>{const dependencyReferences=Array.isArray(item.depends_on_ids)?item.depends_on_ids:[],dependencies=dependencyReferences.map((reference:string)=>workItemByReference.get(reference)).filter(Boolean).map((dependency:any)=>({id:dependency.id,title:dependency.title,state:dependency.state})),dependency_blocked=dependencies.filter((dependency:any)=>dependency.state!=='MERGED_TO_PHASE'),next_action=item.external_blocked?'Aguardando a resolução do bloqueio externo.':dependency_blocked.length?`Aguardando conclusão de: ${dependency_blocked.map((dependency:any)=>dependency.title).join(', ')}.`:nextAction(item.state,item.blocked_kind);return publicValue({...item,depends_on_ids:dependencyReferences,dependencies,dependency_blocked,next_action});});
  const review=modulePlanReview(modules.rows,plans.rows,gates.rows);
  // The review endpoint intentionally does not expose raw plan payloads, prompt context,
  // job payloads or idempotency keys. module_plan_review is the sole public plan contract.
  return {modules:expose(modules.rows),work_items:projectedWorkItems,deliveries:expose(deliveries.rows),findings:expose(findings.rows),candidates:expose(candidates.rows),gates:expose(gates.rows),planning_jobs:expose(planningJobs.rows),planning_operations:expose(planningOperations.rows),module_plan_review:review,planning,planning_telemetry:planningTelemetry.rows.map((row:any)=>publicValue(row)),evidence:artifacts.rows};
};

export const materializationBaselineOptions=async(projectId:string)=>{
  const project=(await pool.query(`SELECT workflow_code,workflow_version FROM projects WHERE id=$1`,[projectId])).rows[0];
  if(!project)throw new ApiError(404,'PROJECT_NOT_FOUND');
  const v3=project.workflow_code==='PROJECT_DISCOVERY'&&Number(project.workflow_version)===3;
  const revisions=v3?(await pool.query(`SELECT id,revision_number FROM technology_baseline_revisions WHERE project_key=$1 AND status='APPROVED' ORDER BY revision_number DESC`,[projectId])).rows:[];
  return { baseline_required:v3, baseline_requirement:v3?'BASELINE_REQUIRED':'BASELINE_NOT_REQUIRED_LEGACY', approved_revisions:revisions };
};

