const reworkInput=(body:Record<string,unknown>)=>{
  const findingIds=Array.isArray(body.finding_ids)?body.finding_ids:[];
  if(!findingIds.length||!findingIds.every(id=>typeof id==='string')||typeof body.delivery_id!=='string'||typeof body.head_sha!=='string'||typeof body.justification!=='string'||!body.justification.trim()) throw new ApiError(422,'REWORK_REFERENCE_REQUIRED');
  return {findingIds,deliveryId:body.delivery_id,headSha:body.head_sha,justification:body.justification.trim().slice(0,2000)};
};
export const authorizeRework=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const w=(await c.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2 FOR UPDATE`,[workItemId,projectId])).rows[0];if(!w)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(w.state!=='REWORK_ELIGIBLE')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const input=reworkInput(body),delivery=(await c.query(`SELECT id,head_sha FROM deliveries WHERE id=$1 AND project_id=$2 AND work_item_id=$3 FOR UPDATE`,[input.deliveryId,projectId,workItemId])).rows[0];if(!delivery||delivery.head_sha!==input.headSha)throw new ApiError(409,'REWORK_DELIVERY_SHA_NOT_PERTINENT');const findings=(await c.query(`SELECT f.id,f.severity FROM findings f JOIN finding_work_items fw ON fw.finding_id=f.id WHERE f.project_id=$1 AND fw.work_item_id=$2 AND f.id=ANY($3::uuid[]) AND f.state='OPEN' FOR UPDATE`,[projectId,workItemId,input.findingIds])).rows;if(findings.length!==input.findingIds.length)throw new ApiError(409,'REWORK_FINDING_NOT_PERTINENT');const correlation=randomUUID(),round=Number(w.rework_rounds)+1,critical=findings.some((x:any)=>x.severity==='CRITICAL'),reason=critical?'CRITICAL_FINDING':round>=3?'REWORK_LIMIT':body.repeated_finding===true?'REPEATED_FINDING':typeof body.scope_change==='string'?'SCOPE_CHANGE':typeof body.architecture_change==='string'?'ARCHITECTURE_CHANGE':null,op=await operation(c,projectId,reason?'ESCALATE_REWORK':'AUTHORIZE_REWORK',idempotencyKey,correlation),decisionId=randomUUID();await c.query(`INSERT INTO rework_decisions(id,project_id,work_item_id,revision_id,delivery_id,head_sha,finding_ids,justification,rework_round,status) VALUES($1,$2,$3,$4,$5,$6,$7::jsonb,$8,$9,$10)`,[decisionId,projectId,workItemId,w.revision_id,input.deliveryId,input.headSha,JSON.stringify(input.findingIds),input.justification,round,reason?'ESCALATED':'ACTIVE']);const record={decision_id:decisionId,work_item_id:workItemId,revision_id:w.revision_id,delivery_id:input.deliveryId,head_sha:input.headSha,finding_ids:input.findingIds,justification:input.justification,limit:2,round,reason,correlation_id:correlation};const artifact=await evidence(c,projectId,'rework-decision',record,op);if(reason){const gateId=randomUUID();await c.query(`INSERT INTO rework_gates(id,project_id,work_item_id,revision_id,decision_id,reason,evidence) VALUES($1,$2,$3,$4,$5,$6,$7)`,[gateId,projectId,workItemId,w.revision_id,decisionId,reason,{rework_decision_hash:artifact.json.hash}]);await c.query(`UPDATE work_items SET state='WAITING_FOR_ESCALATION',version=version+1 WHERE id=$1`,[workItemId]);await event(c,projectId,'REWORK_ESCALATED',correlation,{...record,gate_id:gateId});return{operation_id:op,status:'ACCEPTED',escalated:true,gate_id:gateId};}await c.query(`UPDATE work_items SET rework_rounds=$2,version=version+1 WHERE id=$1`,[workItemId,round]);await c.query(`UPDATE findings SET state='FIXED_PENDING_REVALIDATION' WHERE id=ANY($1::uuid[])`,[input.findingIds]);await event(c,projectId,'REWORK_AUTHORIZED',correlation,record);return{operation_id:op,status:'ACCEPTED',escalated:false,decision_id:decisionId};});

export const decideReworkGate=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const gate=(await c.query(`SELECT g.*,d.rework_round FROM rework_gates g JOIN rework_decisions d ON d.id=g.decision_id WHERE g.project_id=$1 AND g.work_item_id=$2 AND g.status='OPEN' FOR UPDATE`,[projectId,workItemId])).rows[0];if(!gate||Number(body.version)!==gate.version||typeof body.decision!=='string'||!['AUTHORIZE_REWORK','ACCEPT_RISK','CHANGE_SCOPE','CHANGE_ARCHITECTURE','CLOSE'].includes(body.decision))throw new ApiError(409,'GATE_VERSION_CONFLICT');const feedback=typeof body.feedback==='string'?body.feedback.trim():'';if(!feedback)throw new ApiError(422,'GATE_FEEDBACK_REQUIRED');const correlation=randomUUID(),op=await operation(c,projectId,'DECIDE_REWORK_GATE',idempotencyKey,correlation),allow=body.decision==='AUTHORIZE_REWORK';await c.query(`UPDATE rework_gates SET status='DECIDED',decision=$2,feedback=$3,decided_at=clock_timestamp() WHERE id=$1`,[gate.id,body.decision,feedback]);await c.query(`UPDATE rework_decisions SET status=$2,resolved_at=clock_timestamp() WHERE id=$1`,[gate.decision_id,allow?'ACTIVE':body.decision==='ACCEPT_RISK'?'RISK_ACCEPTED':'CLOSED']);if(allow){await c.query(`UPDATE work_items SET rework_rounds=$2,state='REWORK_ELIGIBLE',version=version+1 WHERE id=$1`,[workItemId,gate.rework_round]);await c.query(`UPDATE findings SET state='FIXED_PENDING_REVALIDATION' WHERE id=ANY(SELECT jsonb_array_elements_text(finding_ids)::uuid FROM rework_decisions WHERE id=$1)`,[gate.decision_id]);}await event(c,projectId,'REWORK_GATE_DECIDED',correlation,{work_item_id:workItemId,gate_id:gate.id,decision:body.decision,feedback});return{operation_id:op,status:'ACCEPTED'};});

