/** Operator recovery for a terminal implementation attempt.  It deliberately
 * reuses only a released, clean reservation; the worker still reconciles it
 * before touching Git.  A source operation can produce one retry lineage. */
export const retryDevelopmentWorkItem=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string,operatorId=config().operatorId)=>withTransaction(async c=>{
  if(!operatorId||operatorId!==config().operatorId)throw new ApiError(403,'OPERATOR_NOT_AUTHORIZED');
  const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};
  const failedOperationId=typeof body.failed_operation_id==='string'?body.failed_operation_id:'';
  if(!failedOperationId)throw new ApiError(422,'FAILED_OPERATION_ID_REQUIRED');
  const source=(await c.query(`SELECT o.*,j.id job_id,j.delivery_id,d.state delivery_state,t.id worktree_id,t.path worktree_path,t.branch,t.base_sha,t.state worktree_state,w.state work_item_state,w.payload,w.revision_id,w.technology_baseline_revision_id,p.repository_path
    FROM operations o JOIN jobs j ON j.operation_id=o.id JOIN deliveries d ON d.id=j.delivery_id JOIN worktrees t ON t.id=d.worktree_id JOIN work_items w ON w.id=d.work_item_id JOIN projects p ON p.id=o.project_id
    WHERE o.id=$1 AND o.project_id=$2 AND o.kind IN ('START_DEVELOPMENT','RETRY_DEVELOP_WORK_ITEM') AND o.status='FAILED' AND w.id=$3 FOR UPDATE`,[failedOperationId,projectId,workItemId])).rows[0];
  if(!source)throw new ApiError(409,'DEVELOPMENT_RETRY_ORIGIN_NOT_ELIGIBLE');
  const repeated=await c.query(`SELECT 1 FROM operations WHERE origin_operation_id=$1`,[failedOperationId]);if(repeated.rowCount)throw new ApiError(409,'DEVELOPMENT_RETRY_ORIGIN_ALREADY_RETRIED');
  if(source.work_item_state!=='REWORK_ELIGIBLE'||!['FAILED','RESERVED'].includes(source.delivery_state)||!['RELEASED','PREPARED'].includes(source.worktree_state))throw new ApiError(409,'DEVELOPMENT_RETRY_RECONCILIATION_REQUIRED');
  const retryCount=Number((await c.query(`WITH RECURSIVE lineage AS (SELECT id,origin_operation_id FROM operations WHERE id=$1 UNION ALL SELECT o.id,o.origin_operation_id FROM operations o JOIN lineage l ON l.origin_operation_id=o.id) SELECT count(*)::int AS count FROM lineage`,[failedOperationId])).rows[0]?.count??0);
  if(retryCount>=config().developmentRetryMaxAttempts)throw new ApiError(409,'DEVELOPMENT_RETRY_LIMIT_EXCEEDED');
  // A terminal job can leave a worktree behind.  Classify it before creating a
  // new lease: clean means reusable; a fully auditable allowed commit is
  // already evidence and must not be executed a second time; everything else
  // is discarded and rebuilt below.
  let reconciliation:'REUSE_CLEAN_RESERVATION'|'RECONCILE_AUDITABLE_EVIDENCE'|'REBUILD_DISCARDED_WORKTREE'='REBUILD_DISCARDED_WORKTREE';
  try {
    if(reconcileWorktree(source.repository_path,source.worktree_path,source.branch,source.base_sha)==='ACTIVE') {
      const head=gitValue(source.worktree_path,'rev-parse','HEAD');
      if(head===source.base_sha) reconciliation='REUSE_CLEAN_RESERVATION';
      else { const paths=assertIncrementalPaths(source.worktree_path,source.base_sha,source.payload?.allowlist??[],source.payload?.denylist??[]); const commits=assertAuditableCommits(source.worktree_path,source.base_sha,workItemId); if(paths.length&&commits.length) reconciliation='RECONCILE_AUDITABLE_EVIDENCE'; }
    }
  } catch { reconciliation='REBUILD_DISCARDED_WORKTREE'; }
  const op=randomUUID(),jobId=randomUUID(),correlation=randomUUID();
  await c.query(`INSERT INTO operations(id,project_id,kind,status,idempotency_key,correlation_id,origin_operation_id) VALUES($1,$2,'RETRY_DEVELOP_WORK_ITEM','QUEUED',$3,$4,$5)`,[op,projectId,idempotencyKey,correlation,failedOperationId]);
  if(reconciliation==='RECONCILE_AUDITABLE_EVIDENCE'){
    const head=gitValue(source.worktree_path,'rev-parse','HEAD'),paths=assertIncrementalPaths(source.worktree_path,source.base_sha,source.payload?.allowlist??[],source.payload?.denylist??[]),commits=assertAuditableCommits(source.worktree_path,source.base_sha,workItemId);
    const artifact=await evidence(c,projectId,'development-retry-reconciliation',{delivery_id:source.delivery_id,work_item_id:workItemId,retry_of_operation_id:failedOperationId,reconciliation,base_sha:source.base_sha,head_sha:head,changed_paths:paths,commits},op);
    await c.query(`UPDATE deliveries SET state='EVIDENCE_REVIEW',head_sha=$2,changed_paths=$3::jsonb,commits=$4::jsonb WHERE id=$1`,[source.delivery_id,head,JSON.stringify(paths),JSON.stringify(commits)]);
    await c.query(`UPDATE worktrees SET state='ACTIVE' WHERE id=$1`,[source.worktree_id]);
    await c.query(`UPDATE work_items SET state='QA_IN_PROGRESS',version=version+1 WHERE id=$1`,[workItemId]);
    await c.query(`UPDATE operations SET status='SUCCEEDED',completed_at=clock_timestamp() WHERE id=$1`,[op]);
    await event(c,projectId,'DEVELOPMENT_RETRY_RECONCILED',correlation,{work_item_id:workItemId,delivery_id:source.delivery_id,retry_of_operation_id:failedOperationId,reconciliation,evidence_hash:artifact.json.hash,next_action:'SUBMIT_QA'});
    return{operation_id:op,status:'ACCEPTED',delivery_id:source.delivery_id,reconciliation};
  }
  if(reconciliation==='REBUILD_DISCARDED_WORKTREE'){
    // The old path is no longer trusted.  Mark it removed before reserving a
    // fresh delivery, which releases both partial unique indexes atomically.
    try { discardWorktree(source.repository_path,source.worktree_path); } catch { throw new ApiError(409,'DEVELOPMENT_RETRY_RECONCILIATION_REQUIRED'); }
    await c.query(`UPDATE worktrees SET state='REMOVED' WHERE id=$1`,[source.worktree_id]);
    await c.query(`UPDATE deliveries SET state='DISCARDED' WHERE id=$1`,[source.delivery_id]);
    const worktreeId=randomUUID(),deliveryId=randomUUID(),path=join(source.repository_path,'.naamive-worktrees',worktreeId),branch=`work-items/${workItemId}-retry-${retryCount+1}`;
    await c.query(`INSERT INTO worktrees(id,project_id,work_item_id,path,branch,base_sha,lease_expires_at,state) VALUES($1,$2,$3,$4,$5,$6,clock_timestamp()+interval '10 minutes','RESERVED')`,[worktreeId,projectId,workItemId,path,branch,source.base_sha]);
    await c.query(`INSERT INTO deliveries(id,project_id,work_item_id,revision_id,worktree_id,base_sha,qa_matrix,technology_baseline_revision_id,state) SELECT $1,project_id,work_item_id,revision_id,$2,$3,qa_matrix,technology_baseline_revision_id,'RESERVED' FROM deliveries WHERE id=$4`,[deliveryId,worktreeId,source.base_sha,source.delivery_id]);
    await c.query(`INSERT INTO jobs(id,operation_id,project_id,revision_id,delivery_id,kind,idempotency_key,technology_baseline_revision_id,origin_operation_id) SELECT $1,$2,$3,NULL,$4,'DEVELOP_WORK_ITEM',$5,technology_baseline_revision_id,$6 FROM deliveries WHERE id=$4`,[jobId,op,projectId,deliveryId,`development-retry:${op}`,failedOperationId]);
    await c.query(`UPDATE deliveries SET job_id=$2 WHERE id=$1`,[deliveryId,jobId]);
    await event(c,projectId,'DEVELOPMENT_RETRY_REQUESTED',correlation,{work_item_id:workItemId,delivery_id:deliveryId,job_id:jobId,retry_of_operation_id:failedOperationId,reconciliation});
    return{operation_id:op,status:'ACCEPTED',delivery_id:deliveryId,reconciliation};
  }
  await c.query(`INSERT INTO jobs(id,operation_id,project_id,revision_id,delivery_id,kind,idempotency_key,technology_baseline_revision_id,origin_operation_id) SELECT $1,$2,$3,NULL,d.id,'DEVELOP_WORK_ITEM',$4,d.technology_baseline_revision_id,$5 FROM deliveries d WHERE d.id=$6`,[jobId,op,projectId,`development-retry:${op}`,failedOperationId,source.delivery_id]);
  await c.query(`UPDATE deliveries SET state='RESERVED',job_id=$2 WHERE id=$1`,[source.delivery_id,jobId]);await c.query(`UPDATE worktrees SET state='PREPARED',lease_expires_at=clock_timestamp()+interval '10 minutes' WHERE id=(SELECT worktree_id FROM deliveries WHERE id=$1)`,[source.delivery_id]);
  await event(c,projectId,'DEVELOPMENT_RETRY_REQUESTED',correlation,{work_item_id:workItemId,delivery_id:source.delivery_id,job_id:jobId,retry_of_operation_id:failedOperationId,reconciliation});
  return{operation_id:op,status:'ACCEPTED',delivery_id:source.delivery_id,reconciliation};
});

export const resolveExternalBlocker=async(projectId:string,workItemId:string,body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const justification=typeof body.justification==='string'?body.justification.trim():'';if(!justification)throw new ApiError(422,'EXTERNAL_BLOCKER_RESOLUTION_REQUIRED');const item=(await c.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2 FOR UPDATE`,[workItemId,projectId])).rows[0];if(!item)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(item.payload?.external_blocked!==true)throw new ApiError(409,'EXTERNAL_BLOCKER_NOT_ACTIVE');const correlation=randomUUID(),op=await operation(c,projectId,'RESOLVE_EXTERNAL_BLOCKER',idempotencyKey,correlation),resolution={justification,resolved_at:new Date().toISOString(),resolved_by:config().operatorId};const payload={...item.payload,external_blocked:false,external_blocked_resolution:resolution};await c.query(`UPDATE work_items SET payload=$2,version=version+1 WHERE id=$1`,[workItemId,payload]);const artifact=await evidence(c,projectId,'external-blocker-resolution',{work_item_id:workItemId,resolution,correlation_id:correlation},op);await event(c,projectId,'WORK_ITEM_EXTERNAL_BLOCKER_RESOLVED',correlation,{work_item_id:workItemId,resolution,evidence_hash:artifact.json.hash});return{operation_id:op,status:'ACCEPTED'};});

/** Rebuilds a delivery's private worktree at the reserved base so an
 * unrecorded or invalid commit from a lost attempt can never be replayed into
 * a changed tree (which would otherwise loop on COMMIT_APPLY_FAILED). */
const rebuildReservedWorktree=(delivery:any)=>{
  try {
    if(gitValue(delivery.path,'rev-parse','HEAD')!==delivery.base_sha){
      discardWorktree(delivery.repository_path,delivery.path);
      discardDeliveryBranch(delivery.repository_path,delivery.branch);
      createWorktree(delivery.repository_path,delivery.path,delivery.branch,delivery.base_sha);
    }
  } catch(error) { throw gitFailure(error); }
};

/** Worker-only Git side effect for a leased development job.  Reservation is
 * not execution: this prepares the environment and marks the attempt
 * DISPATCHED.  The attempt becomes RUNNING only when the orchestration layer
 * emits real execution-start evidence (see executeDevelopmentAgent). */
export const prepareDevelopmentJob=async(job:any)=>{
  const delivery=(await pool.query(`SELECT d.*,t.path,t.branch,t.base_sha,t.state worktree_state,w.id work_item_id,w.state work_item_state,w.payload,p.repository_path,p.initial_sha FROM deliveries d JOIN worktrees t ON t.id=d.worktree_id JOIN work_items w ON w.id=d.work_item_id JOIN projects p ON p.id=d.project_id WHERE d.id=$1`,[job.delivery_id])).rows[0];
  if(!delivery)throw new ApiError(409,'DELIVERY_NOT_FOUND');
  // A retry reuses the reserved attempt/worktree deterministically; it never
  // creates a competing delivery for the same work item.
  if(delivery.state==='RESERVED'&&delivery.worktree_state==='PREPARED'&&['WAITING_FOR_WORK_ITEM_AUTHORIZATION','REWORK_ELIGIBLE'].includes(delivery.work_item_state)){
    // A failed dispatch can have already written an unrecorded or invalid
    // commit before the worker lost control.  Reusing that branch makes every
    // following agent attempt cherry-pick the same files into a changed tree,
    // producing an endless DEVELOPMENT_AGENT_COMMIT_APPLY_FAILED loop.  This
    // delivery has no persisted head/evidence yet, so rebuild its private
    // worktree at the reserved base before giving it back to the executor.
    rebuildReservedWorktree(delivery);
    await withTransaction(async c=>{await c.query(`UPDATE deliveries SET state='DISPATCHED' WHERE id=$1`,[delivery.id]);await c.query(`UPDATE worktrees SET state='ACTIVE',lease_expires_at=clock_timestamp()+interval '10 minutes' WHERE id=$1`,[delivery.worktree_id]);await c.query(`UPDATE work_items SET state='DEVELOPMENT_IN_PROGRESS',version=version+1 WHERE id=$1`,[delivery.work_item_id]);await event(c,delivery.project_id,'DEVELOPMENT_REDISPATCHED',job.operation_id,{work_item_id:delivery.work_item_id,delivery_id:delivery.id,job_id:job.id});});
    return delivery;
  }
  // A prior lease prepared (or started) this attempt but died before evidence
  // was persisted.  The delivery/worktree are still usable, so re-dispatch
  // deterministically instead of silently skipping: rebuild to the reserved
  // base and hand the attempt back to the executor.  The single-active-job
  // index guarantees this job is the only executable attempt for the delivery.
  if((delivery.state==='DISPATCHED'||delivery.state==='RUNNING')&&delivery.worktree_state==='ACTIVE'&&delivery.work_item_state==='DEVELOPMENT_IN_PROGRESS'){
    rebuildReservedWorktree(delivery);
    await withTransaction(async c=>{await c.query(`UPDATE deliveries SET state='DISPATCHED' WHERE id=$1`,[delivery.id]);await c.query(`UPDATE worktrees SET state='ACTIVE',lease_expires_at=clock_timestamp()+interval '10 minutes' WHERE id=$1`,[delivery.worktree_id]);await event(c,delivery.project_id,'DEVELOPMENT_REDISPATCHED',job.operation_id,{work_item_id:delivery.work_item_id,delivery_id:delivery.id,job_id:job.id});});
    return delivery;
  }
  // Never silently skip dispatch: an unexpected state must fail visible so the
  // worker terminates the job instead of falling into a no-op retry loop that
  // never invokes the agent.
  if(delivery.work_item_state!=='WAITING_FOR_WORK_ITEM_AUTHORIZATION'&&delivery.work_item_state!=='REWORK_ELIGIBLE') throw new ApiError(409,'DEVELOPMENT_DISPATCH_STATE_INVALID');
  await discardStaleWorktrees(delivery.project_id,delivery.repository_path,delivery.path); pruneWorktrees(delivery.repository_path);
  let base:string;
  try { const rejected=delivery.work_item_state==='REWORK_ELIGIBLE'?(await pool.query(`SELECT head_sha FROM deliveries WHERE work_item_id=$1 AND state='QA_REJECTED' AND head_sha IS NOT NULL ORDER BY created_at DESC LIMIT 1`,[delivery.work_item_id])).rows[0]:null; base=String(rejected?.head_sha??initializePhaseRefs(delivery.repository_path,delivery.initial_sha).phaseSha); const released=await pool.query(`SELECT id,path FROM worktrees WHERE project_id=$1 AND state='RELEASED' ORDER BY created_at LIMIT 1`,[delivery.project_id]); if(released.rowCount){removeWorktree(delivery.repository_path,released.rows[0].path);await pool.query(`UPDATE worktrees SET state='REMOVED' WHERE id=$1`,[released.rows[0].id]);} mkdirSync(join(delivery.repository_path,'.naamive-worktrees'),{recursive:true}); createWorktree(delivery.repository_path,delivery.path,delivery.branch,base); }
  catch(error) { throw gitFailure(error); }
  await withTransaction(async c=>{const artifact=await evidence(c,delivery.project_id,'development-delivery',{delivery_id:delivery.id,work_item_id:delivery.work_item_id,branch:delivery.branch,base_sha:base,job_id:job.id},job.operation_id);await c.query(`UPDATE worktrees SET state='ACTIVE',base_sha=$2,lease_expires_at=clock_timestamp()+interval '10 minutes' WHERE id=$1`,[delivery.worktree_id,base]);await c.query(`UPDATE deliveries SET base_sha=$2,state='DISPATCHED' WHERE id=$1`,[delivery.id,base]);await c.query(`UPDATE work_items SET state='DEVELOPMENT_IN_PROGRESS',version=version+1 WHERE id=$1`,[delivery.work_item_id]);await event(c,delivery.project_id,'DEVELOPMENT_DISPATCHED',job.operation_id,{work_item_id:delivery.work_item_id,delivery_id:delivery.id,job_id:job.id,branch:delivery.branch,base_sha:base,evidence_hash:artifact.json.hash});});
  return {...delivery,base_sha:base};
};

/** Post-executor acceptance is deliberately deterministic: an agent completing
 * its process is insufficient without an allowlisted, auditable commit. */
export const finalizeDevelopmentJob=async(job:any)=>{
  const d=(await pool.query(`SELECT d.*,t.path,w.payload,w.id AS work_item_id FROM deliveries d JOIN worktrees t ON t.id=d.worktree_id JOIN work_items w ON w.id=d.work_item_id WHERE d.id=$1`,[job.delivery_id])).rows[0];
  if(!d)throw new ApiError(409,'DELIVERY_NOT_FOUND');
  const head=gitValue(d.path,'rev-parse','HEAD');
  try { assertAuditableCommits(d.path,d.base_sha,d.work_item_id,head); assertIncrementalPaths(d.path,d.base_sha,d.payload.allowlist,d.payload.denylist); }
  catch(error){throw error instanceof ApiError?error:gitFailure(error);}
  await withTransaction(async c=>{const artifact=await evidence(c,d.project_id,'development-execution-evidence',{delivery_id:d.id,work_item_id:d.work_item_id,job_id:job.id,base_sha:d.base_sha,head_sha:head},job.operation_id);await c.query(`UPDATE deliveries SET head_sha=$2,state='EVIDENCE_REVIEW' WHERE id=$1`,[d.id,head]);await c.query(`UPDATE work_items SET state='QA_IN_PROGRESS',version=version+1 WHERE id=$1`,[d.work_item_id]);await event(c,d.project_id,'DEVELOPMENT_EVIDENCE_READY',randomUUID(),{work_item_id:d.work_item_id,delivery_id:d.id,job_id:job.id,head_sha:head,evidence_hash:artifact.json.hash,next_action:'SUBMIT_QA'});});
};

export const submitQa=async(projectId:string,workItemId:string,_body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const w=(await c.query(`SELECT * FROM work_items WHERE id=$1 AND project_id=$2 FOR UPDATE`,[workItemId,projectId])).rows[0];if(!w)throw new ApiError(404,'WORK_ITEM_NOT_FOUND');if(w.state!=='QA_IN_PROGRESS')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const d=(await c.query(`SELECT d.*,t.path,t.branch FROM deliveries d JOIN worktrees t ON t.id=d.worktree_id WHERE d.work_item_id=$1 AND d.state='EVIDENCE_REVIEW' ORDER BY d.created_at DESC LIMIT 1 FOR UPDATE`,[workItemId])).rows[0];if(!d)throw new ApiError(409,'DELIVERY_NOT_READY_FOR_QA');let head:string,changed:string[],commits:string[],results:any[];const matrix=qaMatrix({qa_matrix:d.qa_matrix}).map((entry:any)=>({...entry}));try{head=gitValue(d.path,'rev-parse','HEAD');commits=assertAuditableCommits(d.path,d.base_sha,workItemId,head);changed=assertIncrementalPaths(d.path,d.base_sha,w.payload.allowlist,w.payload.denylist);if(!changed.length)throw new ApiError(409,'GIT_DIVERGED');results=runMatrix(d.path,matrix);}catch(error){if(error instanceof ApiError)throw error;/* An untrusted worktree is a divergence from the accepted delivery, not a client-visible policy detail. */if((error as any)?.code==='GIT_POLICY_VIOLATION')throw new ApiError(409,'GIT_DIVERGED');throw gitFailure(error);}const failed=results.filter(x=>!x.passed),correlation=randomUUID(),op=await operation(c,projectId,'SUBMIT_QA',idempotencyKey,correlation);await c.query(`UPDATE deliveries SET head_sha=$2,commits=$3::jsonb,validations=$4::jsonb,state='QA_IN_PROGRESS' WHERE id=$1`,[d.id,head,JSON.stringify(commits),JSON.stringify(results)]);for(const result of failed)await qaFinding(c,projectId,{deliveryId:d.id},'DELIVERY_QA',result,workItemId);const blocking=failed.length>0;await c.query(`UPDATE deliveries SET state=$2 WHERE id=$1`,[d.id,blocking?'QA_REJECTED':'QA_APPROVED']);if(blocking)await c.query(`UPDATE worktrees SET state='RELEASED' WHERE id=$1`,[d.worktree_id]);await c.query(`UPDATE work_items SET state=$2,version=version+1 WHERE id=$1`,[workItemId,blocking?'REWORK_ELIGIBLE':'READY_FOR_PHASE_MERGE']);await c.query(`UPDATE rework_decisions SET status='RESOLVED',resolved_at=clock_timestamp() WHERE work_item_id=$1 AND revision_id=$2 AND status='ACTIVE'`,[workItemId,w.revision_id]);if(!blocking)await c.query(`UPDATE findings SET state='CLOSED',revalidation_delivery_id=$2 WHERE state='FIXED_PENDING_REVALIDATION' AND delivery_id IN (SELECT id FROM deliveries WHERE work_item_id=$1 AND created_at < (SELECT created_at FROM deliveries WHERE id=$2))`,[workItemId,d.id]);await evidence(c,projectId,'qa-report',{delivery_id:d.id,work_item_id:workItemId,base_sha:d.base_sha,head_sha:head,commits,changed_paths:changed,matrix,results,correlation_id:correlation},op);await event(c,projectId,blocking?'QA_REJECTED':'QA_APPROVED',correlation,{work_item_id:workItemId,delivery_id:d.id,head_sha:head});return{operation_id:op,status:'ACCEPTED',approved:!blocking};});

export const mergeWorkItemToPhase=async(projectId:string,workItemId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);const row=(await pool.query(`SELECT w.*,d.head_sha,d.worktree_id FROM work_items w JOIN deliveries d ON d.work_item_id=w.id WHERE w.id=$1 AND w.project_id=$2 AND d.state='QA_APPROVED' ORDER BY d.created_at DESC LIMIT 1`,[workItemId,projectId])).rows[0];if(!row||row.state!=='READY_FOR_PHASE_MERGE')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');let phaseSha:string;try{phaseSha=mergeWorkItem(repository.repository_path,'phases/3',`work-items/${workItemId}`,row.head_sha);}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const correlation=randomUUID(),op=await operation(c,projectId,'MERGE_WORK_ITEM_TO_PHASE',idempotencyKey,correlation);await c.query(`UPDATE worktrees SET state='RELEASED' WHERE id=$1`,[row.worktree_id]);await c.query(`UPDATE work_items SET state='MERGED_TO_PHASE',version=version+1 WHERE id=$1`,[workItemId]);await event(c,projectId,'WORK_ITEM_MERGED_TO_PHASE',correlation,{work_item_id:workItemId,phase_sha:phaseSha});return{operation_id:op,status:'ACCEPTED',phase_sha:phaseSha};});};

export const createCandidate=async(projectId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);let phaseSha:string;try{phaseSha=gitValue(repository.repository_path,'rev-parse','phases/3');}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const rows=(await c.query(`SELECT w.id AS work_item_id,w.payload->'qa_matrix' AS qa_matrix,w.technology_baseline_revision_id,d.head_sha,d.commits FROM work_items w JOIN LATERAL (SELECT head_sha,commits FROM deliveries WHERE work_item_id=w.id AND state='QA_APPROVED' ORDER BY created_at DESC LIMIT 1) d ON true WHERE w.project_id=$1 AND w.state='MERGED_TO_PHASE' ORDER BY w.created_at`,[projectId])).rows;if(!rows.length)throw new ApiError(409,'INTEGRATION_CANDIDATE_EMPTY');const items=rows.map((item:any)=>({work_item_id:item.work_item_id,technology_baseline_revision_id:baselineReference(item.technology_baseline_revision_id),head_sha:item.head_sha,commits:item.commits,qa_matrix:qaMatrix(item)}));const correlation=randomUUID(),op=await operation(c,projectId,'CREATE_INTEGRATION_CANDIDATE',idempotencyKey,correlation),id=randomUUID(),manifest={phase_sha:phaseSha,work_items:items};await c.query(`INSERT INTO integration_candidates(id,project_id,phase_sha,manifest) VALUES($1,$2,$3,$4)`,[id,projectId,phaseSha,manifest]);await evidence(c,projectId,'integration-candidate-manifest',{candidate_id:id,manifest,correlation_id:correlation},op);await event(c,projectId,'INTEGRATION_CANDIDATE_CREATED',correlation,{candidate_id:id,phase_sha:phaseSha,manifest});return{operation_id:op,status:'ACCEPTED',candidate_id:id};});};

export const validateCandidate=async(projectId:string,candidateId:string,_body:Record<string,unknown>,idempotencyKey:string)=>withTransaction(async c=>{const prior=await idem(c,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='CANDIDATE_CREATED')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const repository=await projectRepository(projectId),entries=(candidate.manifest?.work_items??[]).flatMap((item:any)=>qaMatrix(item).map((entry:any)=>({...entry,work_item_id:item.work_item_id}))),matrix=entries.map(({work_item_id,...entry}:any)=>entry),temporary=join(repository.repository_path,'.naamive-candidates',candidateId);let results:any[];try{if(gitValue(repository.repository_path,'rev-parse',candidate.phase_sha)!==candidate.phase_sha)throw new ApiError(409,'GIT_DIVERGED');mkdirSync(join(repository.repository_path,'.naamive-candidates'),{recursive:true});execFileSync('git',['-C',repository.repository_path,'worktree','add','--detach',temporary,candidate.phase_sha]);results=runMatrix(temporary,matrix).map((result:any)=>({...result,work_item_id:entries[result.index].work_item_id}));}catch(error){throw error instanceof ApiError?error:gitFailure(error);}finally{try{execFileSync('git',['-C',repository.repository_path,'worktree','remove','--force',temporary]);}catch{}}const failed=results.filter(x=>!x.passed),correlation=randomUUID(),op=await operation(c,projectId,'VALIDATE_INTEGRATION_CANDIDATE',idempotencyKey,correlation);for(const result of failed)await qaFinding(c,projectId,{candidateId},'CANDIDATE_VALIDATION',result,result.work_item_id);await c.query(`UPDATE integration_candidates SET state=$2,blocked_kind=$3,version=version+1 WHERE id=$1`,[candidateId,failed.length?'INTEGRATION_BLOCKED':'INTEGRATION_PENDING',failed.length?'VALIDATION_CODE_DEFECT':null]);await evidence(c,projectId,'integration-candidate-validation',{candidate_id:candidateId,phase_sha:candidate.phase_sha,manifest:candidate.manifest,matrix:entries,results,correlation_id:correlation},op);await event(c,projectId,failed.length?'CANDIDATE_VALIDATION_FAILED':'CANDIDATE_VALIDATED',correlation,{candidate_id:candidateId,phase_sha:candidate.phase_sha});return{operation_id:op,status:'ACCEPTED',approved:!failed.length};});

export const startIntegration=async(projectId:string,candidateId:string,_body:Record<string,unknown>,idempotencyKey:string)=>{const prior=await idem(pool,idempotencyKey);if(prior)return{operation_id:prior,status:'ACCEPTED'};const repository=await projectRepository(projectId);let before:string;try{before=gitValue(repository.repository_path,'rev-parse','integration');}catch(error){throw gitFailure(error);}const reserved=await withTransaction(async c=>{const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_PENDING')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');if(gitValue(repository.repository_path,'rev-parse','phases/3')!==candidate.phase_sha)throw new ApiError(409,'GIT_DIVERGED');const correlation=randomUUID(),op=await operation(c,projectId,'START_INTEGRATION',idempotencyKey,correlation),attempt=randomUUID();await c.query(`INSERT INTO integration_attempts(id,project_id,candidate_id,idempotency_key,integration_before_sha,candidate_sha,state) VALUES($1,$2,$3,$4,$5,$6,'RESERVED')`,[attempt,projectId,candidateId,idempotencyKey,before,candidate.phase_sha]);await evidence(c,projectId,'integration-attempt-intent',{attempt_id:attempt,candidate_id:candidateId,integration_before_sha:before,candidate_sha:candidate.phase_sha,expected_parents:[before,candidate.phase_sha],operation:'merge-and-push-detached',correlation_id:correlation},op);await c.query(`UPDATE integration_candidates SET state='INTEGRATION_IN_PROGRESS',version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_ATTEMPT_RESERVED',correlation,{candidate_id:candidateId,attempt_id:attempt,integration_before_sha:before,candidate_sha:candidate.phase_sha});return{attempt,op,correlation,candidate};});let result:any;try{result=mergeAndPushDetached(repository.repository_path,'phases/3','integration',reserved.candidate.phase_sha,before);}catch(error){const code=(error as any)?.code??'GIT_DIVERGED',blocked=code==='GIT_DIVERGED'?'GIT_DIVERGED':'GIT_RECOVERABLE';await pool.query(`UPDATE integration_attempts SET state='FAILED' WHERE id=$1`,[reserved.attempt]);await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind=$2,version=version+1 WHERE id=$1`,[candidateId,blocked]);throw new ApiError(409,code);}return withTransaction(async c=>{await c.query(`UPDATE integration_attempts SET merge_sha=$2,push_sha=$2,state='INTEGRATED' WHERE id=$1`,[reserved.attempt,result.mergeSha]);await c.query(`UPDATE integration_candidates SET state='INTEGRATED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);await evidence(c,projectId,'integration-attempt',{attempt_id:reserved.attempt,candidate_id:candidateId,integration_before_sha:before,candidate_sha:reserved.candidate.phase_sha,merge_sha:result.mergeSha,push_sha:result.mergeSha,parents:[before,reserved.candidate.phase_sha]},reserved.op);await event(c,projectId,'INTEGRATION_COMPLETED',reserved.correlation,{candidate_id:candidateId,attempt_id:reserved.attempt,merge_sha:result.mergeSha});return{operation_id:reserved.op,status:'ACCEPTED',attempt_id:reserved.attempt,merge_sha:result.mergeSha};});};

export const revalidateCandidate=async(projectId:string,candidateId:string,body:Record<string,unknown>,key:string)=>{await pool.query(`UPDATE integration_candidates SET state='CANDIDATE_CREATED',blocked_kind=NULL,version=version+1 WHERE id=$1 AND project_id=$2 AND state='INTEGRATION_BLOCKED' AND blocked_kind='VALIDATION_TRANSIENT'`,[candidateId,projectId]);return validateCandidate(projectId,candidateId,body,key);};
export const retryIntegration=async(projectId:string,candidateId:string,body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0],attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_BLOCKED'||candidate.blocked_kind!=='GIT_RECOVERABLE'||!attempt)throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const repository=await projectRepository(projectId);let result:string;try{result=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,attempt.candidate_sha);}catch(error){throw gitFailure(error);}if(result==='APPLIED_UNRECORDED'){await pool.query(`UPDATE integration_attempts SET state='INTEGRATED',merge_sha=coalesce(merge_sha,$2),push_sha=coalesce(push_sha,$2) WHERE id=$1`,[attempt.id,gitValue(repository.repository_path,'rev-parse','origin/integration')]);await pool.query(`UPDATE integration_candidates SET state='INTEGRATED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);return{status:'ACCEPTED',result};}if(result==='DIVERGED'){await pool.query(`UPDATE integration_candidates SET blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);throw new ApiError(409,'GIT_DIVERGED');}await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_PENDING',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);return startIntegration(projectId,candidateId,body,key);};
export const supersedeCandidate=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>withTransaction(async c=>{const old=await idem(c,key);if(old)return{operation_id:old,status:'ACCEPTED'};const candidate=(await c.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2 FOR UPDATE`,[candidateId,projectId])).rows[0];if(!candidate||candidate.state!=='INTEGRATION_BLOCKED'||candidate.blocked_kind!=='VALIDATION_CODE_DEFECT')throw new ApiError(409,'WORKFLOW_TRANSITION_NOT_ALLOWED');const responsible=await c.query(`SELECT DISTINCT work_item_id FROM finding_work_items WHERE finding_id IN (SELECT id FROM findings WHERE candidate_id=$1 AND state='OPEN')`,[candidateId]);if(!responsible.rowCount)throw new ApiError(409,'CANDIDATE_FINDING_RESPONSIBILITY_REQUIRED');const op=await operation(c,projectId,'SUPERSEDE_CANDIDATE',key,randomUUID());await c.query(`UPDATE integration_candidates SET state='SUPERSEDED',version=version+1 WHERE id=$1`,[candidateId]);await c.query(`UPDATE work_items SET state='REWORK_ELIGIBLE',version=version+1 WHERE id=ANY($1::uuid[])`,[responsible.rows.map((x:any)=>x.work_item_id)]);await c.query(`UPDATE modules SET state='WORK_ITEMS_ACTIVE',version=version+1 WHERE id IN (SELECT DISTINCT module_id FROM work_items WHERE id=ANY($1::uuid[]))`,[responsible.rows.map((x:any)=>x.work_item_id)]);await event(c,projectId,'MODULE_REOPENED_FOR_CANDIDATE_FINDING',randomUUID(),{candidate_id:candidateId,work_item_ids:responsible.rows.map((x:any)=>x.work_item_id)});await event(c,projectId,'CANDIDATE_SUPERSEDED',randomUUID(),{candidate_id:candidateId});return{operation_id:op,status:'ACCEPTED'};});
export const reconcileIntegrationAttempt=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0];if(!candidate)throw new ApiError(404,'CANDIDATE_NOT_FOUND');const repository=await projectRepository(projectId);const attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];if(!attempt)throw new ApiError(409,'INTEGRATION_ATTEMPT_NOT_FOUND');let state:string;try{state=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,candidate.phase_sha);}catch(error){throw gitFailure(error);}return withTransaction(async c=>{const op=await operation(c,projectId,'RECONCILE_INTEGRATION',key,randomUUID());if(state==='APPLIED_UNRECORDED')await c.query(`UPDATE integration_candidates SET state='INTEGRATED',version=version+1 WHERE id=$1`,[candidateId]);else if(state==='NOT_APPLIED')await c.query(`UPDATE integration_candidates SET state='INTEGRATION_PENDING',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);else await c.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_RECONCILED',randomUUID(),{candidate_id:candidateId,result:state});return{operation_id:op,status:'ACCEPTED',result:state};});};
export const archiveIntegration=async(projectId:string,candidateId:string,_body:Record<string,unknown>,key:string)=>{const candidate=(await pool.query(`SELECT * FROM integration_candidates WHERE id=$1 AND project_id=$2`,[candidateId,projectId])).rows[0];if(!candidate)throw new ApiError(404,'CANDIDATE_NOT_FOUND');const attempt=(await pool.query(`SELECT * FROM integration_attempts WHERE candidate_id=$1 ORDER BY created_at DESC LIMIT 1`,[candidateId])).rows[0];let remoteState='NO_ATTEMPT';if(attempt){const repository=await projectRepository(projectId);try{remoteState=reconcileIntegration(repository.repository_path,'integration',attempt.integration_before_sha,attempt.candidate_sha);}catch(error){throw gitFailure(error);}if(remoteState==='DIVERGED'){await pool.query(`UPDATE integration_candidates SET state='INTEGRATION_BLOCKED',blocked_kind='GIT_DIVERGED',version=version+1 WHERE id=$1`,[candidateId]);throw new ApiError(409,'ARCHIVE_RECONCILIATION_REQUIRED');}}return withTransaction(async c=>{const old=await idem(c,key);if(old)return{operation_id:old,status:'ACCEPTED'};const op=await operation(c,projectId,'ARCHIVE_INTEGRATION',key,randomUUID());if(remoteState==='APPLIED_UNRECORDED')await c.query(`UPDATE integration_attempts SET state='INTEGRATED' WHERE id=$1`,[attempt.id]);await c.query(`UPDATE integration_candidates SET state='ARCHIVED',blocked_kind=NULL,version=version+1 WHERE id=$1`,[candidateId]);await event(c,projectId,'INTEGRATION_ARCHIVED',randomUUID(),{candidate_id:candidateId,remote_reconciliation:remoteState});return{operation_id:op,status:'ACCEPTED'};});};

export const reconcileDevelopmentWorktree=async(projectId:string,workItemId:string,key:string)=>withTransaction(async c=>{const prior=await idem(c,key);if(prior)return{operation_id:prior,status:'ACCEPTED'};const tree=(await c.query(`SELECT t.* FROM worktrees t WHERE t.project_id=$1 AND t.work_item_id=$2 AND t.state IN ('ACTIVE','RESERVED') ORDER BY t.created_at DESC LIMIT 1 FOR UPDATE`,[projectId,workItemId])).rows[0];if(!tree)throw new ApiError(404,'WORKTREE_NOT_FOUND');const repository=await projectRepository(projectId);let result;try{result=reconcileWorktree(repository.repository_path,tree.path,tree.branch,tree.base_sha);}catch(error){throw gitFailure(error);}const op=await operation(c,projectId,'RECONCILE_WORKTREE',key,randomUUID());if(result==='ACTIVE')await c.query(`UPDATE worktrees SET lease_expires_at=clock_timestamp()+interval '10 minutes',state='ACTIVE' WHERE id=$1`,[tree.id]);else{await c.query(`UPDATE worktrees SET state='BLOCKED' WHERE id=$1`,[tree.id]);await c.query(`UPDATE work_items SET state='WAITING_FOR_ESCALATION',version=version+1 WHERE id=$1`,[workItemId]);}await event(c,projectId,'WORKTREE_RECONCILED',randomUUID(),{work_item_id:workItemId,worktree_id:tree.id,result});return{operation_id:op,status:'ACCEPTED',result};});
